def is_user_source(filepath):
    """判断文件是否可能包含用户原话"""
    path_str = str(filepath)
    # 排除AI写的内容
    for excl in EXCLUDE_SOURCES:
        if excl in path_str:
            return False
    return True

def extract_user_quotes(filepath):
    """从文件提取用户原话"""
    quotes = []
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            content = f.read()
    except:
        return quotes
    
    for src in USER_SOURCES:
        matches = re.findall(src['pattern'], content, src['flags'])
        for m in matches:
            if isinstance(m, tuple):
                m = m[0]
            m = m.strip()
            m = re.sub(r'\s+', ' ', m)
            if 8 < len(m) < 400:
                # 过滤明显不是用户原话的
                if not any(x in m for x in ['智能体', 'AI说', '模型说', '工具调用', 'function call', 'token', 'schema', '参数', '返回']):
                    quotes.append({'text': m, 'type': src['type'], 'source': str(filepath.relative_to(REPO))})
    return quotes

def classify_quote(text):
    """按生命论结构分类"""
    scores = {}
    for cat, config in CATEGORIES.items():
        score = 0
        for kw in config['keywords']:
            if kw in text:
                score += config['weight']
        if score > 0:
            scores[cat] = score
    
    if not scores:
        return '其他'
    return max(scores, key=scores.get)

