def main():
    all_quotes = []
    
    # 扫描所有md文件
    md_files = list(REPO.rglob("*.md"))
    print(f"扫描 {len(md_files)} 个md文件...")
    
    for f in md_files:
        if not is_user_source(f):
            continue
        if '.git' in str(f) or 'node_modules' in str(f):
            continue
        quotes = extract_user_quotes(f)
        all_quotes.extend(quotes)
    
    print(f"初步提取 {len(all_quotes)} 条")
    
    # 去重
    seen = set()
    unique_quotes = []
    for q in all_quotes:
        norm = re.sub(r'\s+', '', q['text'])[:80]
        if norm not in seen:
            seen.add(norm)
            unique_quotes.append(q)
    
    print(f"去重后 {len(unique_quotes)} 条")
    
    # 筛选高质量
    high_quality = [q for q in unique_quotes if is_high_quality(q['text'])]
    print(f"高质量 {len(high_quality)} 条")
    
    # 分类
    categorized = defaultdict(list)
    for q in high_quality:
        cat = classify_quote(q['text'])
        categorized[cat].append(q)
    
    print("\n=== 分类统计 ===")
    for cat, quotes in sorted(categorized.items(), key=lambda x: -len(x[1])):
        print(f"  {len(quotes):4d}  {cat}")
    
    # 保存
    output = {
        'total': len(high_quality),
        'categories': {cat: [{'text': q['text'], 'source': q['source'], 'type': q['type']} for q in quotes]
                       for cat, quotes in categorized.items()}
    }
    
    output_path = REPO / "docs" / "raw_materials" / "金句录_精细分类.json"
    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(output, f, ensure_ascii=False, indent=2)
    print(f"\n已保存到 {output_path}")

if __name__ == "__main__":
    main()
